const { useState } = React;

function ProductForm() {
  const [name, setName] = useState('');
  const [products, setProducts] = useState([]);
  function addProduct() {
    if (!name) return;
    setProducts((previous) => [...previous, { id: previous.length + 1, name }]);
    setName('');
  }
  return (
    <section>
      <input aria-label="상품 이름" value={name} onChange={(event) => setName(event.target.value)} />
      <button type="button" onClick={addProduct}>추가</button>
      <ul>{products.map((product) => <li key={product.id}>{product.name}</li>)}</ul>
    </section>
  );
}
ReactDOM.createRoot(document.querySelector('#root')).render(<ProductForm />);
